const el = root.querySelector('.m-otp-code-shake');
if (!el) return function () {};
const row = el.querySelector('.m-otp-code-shake__row');
const boxes = Array.prototype.slice.call(el.querySelectorAll('.m-otp-code-shake__box'));
const reduce = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
const timers = new Set();

function later(fn, ms) {
  const id = setTimeout(function () { timers.delete(id); fn(); }, ms);
  timers.add(id);
}
function clearTimers() {
  timers.forEach(clearTimeout);
  timers.clear();
}
function activate(index) {
  boxes.forEach(function (box, i) { box.classList.toggle('is-active', i === index); });
}

// Beat 1: digits land one by one, the focus ring walks ahead of them.
function type() {
  if (!root.isConnected) return;
  activate(0);
  boxes.forEach(function (box, i) {
    later(function () {
      box.classList.add('is-filled');
      activate(i + 1);
    }, 320 + i * 190);
  });
  later(reject, 320 + boxes.length * 190 + 240);
}

// Beat 2: the row shakes with a damped oscillation and the message fades in.
function reject() {
  activate(-1);
  boxes.forEach(function (box) { box.classList.add('is-filled'); });
  el.classList.add('is-error');
  row.classList.remove('is-shaking');
  void row.offsetWidth; // restart the keyframes
  row.classList.add('is-shaking');
  if (!reduce) later(clear, 1700);
}

// Beat 3: digits clear right to left, then the loop starts over.
function clear() {
  el.classList.remove('is-error');
  row.classList.remove('is-shaking');
  boxes.forEach(function (box, i) {
    later(function () { box.classList.remove('is-filled'); }, (boxes.length - 1 - i) * 45);
  });
  later(type, 520);
}

function onClick() {
  clearTimers();
  reject();
}

el.addEventListener('click', onClick);
if (reduce) reject(); else type();

return function dispose() {
  clearTimers();
  el.removeEventListener('click', onClick);
};

