js:
const el = root.querySelector('.m-elastic-slider');
if (!el) return function () {};
const track = el.querySelector('.m-elastic-slider__track');
const rail = el.querySelector('.m-elastic-slider__rail');
const fill = el.querySelector('.m-elastic-slider__fill');
const thumb = el.querySelector('.m-elastic-slider__thumb');
const num = el.querySelector('.m-elastic-slider__num');
const ticks = Array.prototype.slice.call(el.querySelectorAll('.m-elastic-slider__ticks i'));
const reduce = window.matchMedia('(prefers-reduced-motion: reduce)').matches;

let width = 200;                    // track length in px
let x = 0, v = 0, to = 0;           // thumb position spring, px
let stretch = 0;                    // smoothed velocity stretch, 0..0.5
let shown = -1;
let dragging = false;
let auto = !reduce, clock = 0, stepIndex = -1, resumeTimer = 0;
let raf = 0, last = 0, alive = true, seen = false, orphan = 0;

// Auto-glide: [value, seconds]. Values outside 0..100 tug past an end, then let go.
const DEMO = [[57, 1.15], [80, 1.15], [109, 0.4], [100, 0.75], [30, 1.15], [-9, 0.4], [0, 0.75]];

// Rubber band: past an end the thumb follows with exponential resistance (max 17% of the track).
function band(px) {
  const limit = width * 0.17;
  if (px > width) return width + limit * (1 - Math.exp(-(px - width) / limit));
  if (px < 0) return -limit * (1 - Math.exp(px / limit));
  return px;
}
function clamp(px) { return Math.max(0, Math.min(width, px)); }

function measure() {
  const next = track.clientWidth || 200;
  const ratio = next / width;
  width = next;
  x *= ratio; to *= ratio; v *= ratio;
}

function render() {
  const sx = 1 + stretch, sy = 1 - stretch * 0.42;
  thumb.style.transform = `translate3d(${x.toFixed(2)}px, 0, 0) scale(${sx.toFixed(4)}, ${sy.toFixed(4)})`;
  num.style.transform = `scale(${(1 / sx).toFixed(4)}, ${(1 / sy).toFixed(4)})`; // keep the digits undistorted
  const left = Math.min(0, x), right = Math.max(width, x);
  rail.style.transform = `translate3d(${left.toFixed(2)}px, 0, 0) scaleX(${((right - left) / width).toFixed(4)})`;
  fill.style.transform = `translate3d(${left.toFixed(2)}px, 0, 0) scaleX(${(Math.max(0, x - left) / width).toFixed(4)})`;
  for (let i = 0; i < ticks.length; i++) {
    const near = Math.exp(-Math.pow((x - (i / (ticks.length - 1)) * width) / (width * 0.075), 2));
    ticks[i].style.transform = `scaleY(${(1 + 1.3 * near).toFixed(3)})`;
    ticks[i].style.opacity = (0.2 + 0.8 * near).toFixed(3);
  }
  const value = Math.round((clamp(x) / width) * 100);
  if (value !== shown) {
    shown = value;
    num.textContent = String(value);
    track.setAttribute('aria-valuenow', String(value));
  }
}

function frame(now) {
  if (!alive) return;
  if (!root.isConnected && (seen || ++orphan > 180)) return dispose();
  seen = seen || root.isConnected;
  const dt = Math.min((now - last) / 1000, 0.032) || 0.016;
  last = now;

  if (auto) {
    clock -= dt;
    if (clock <= 0) {
      stepIndex = (stepIndex + 1) % DEMO.length;
      to = band((DEMO[stepIndex][0] / 100) * width);
      clock = DEMO[stepIndex][1];
    }
  }
  if (reduce) {
    x = clamp(to); v = 0; stretch = 0;
  } else {
    // Stiffer while held so the thumb stays under the finger, looser on release so it rings.
    const k = dragging ? 520 : 260, c = dragging ? 34 : 20;
    v += (-k * (x - to) - c * v) * dt;
    x += v * dt;
    const want = Math.min(0.5, (Math.abs(v) / width) * 0.11);
    stretch += (want - stretch) * Math.min(1, dt * 18);
  }
  render();
  raf = requestAnimationFrame(frame);
}

function pointerX(e) { return e.clientX - track.getBoundingClientRect().left; }
function onDown(e) {
  auto = false;
  clearTimeout(resumeTimer);
  dragging = true;
  to = band(pointerX(e));
  if (el.setPointerCapture) { try { el.setPointerCapture(e.pointerId); } catch (err) {} }
}
function onMove(e) { if (dragging) to = band(pointerX(e)); }
function onUp() {
  if (!dragging) return;
  dragging = false;
  to = clamp(to); // release: snap back inside the track
}
function onKey(e) {
  const delta = e.key === 'ArrowRight' || e.key === 'ArrowUp' ? 5 : e.key === 'ArrowLeft' || e.key === 'ArrowDown' ? -5 : 0;
  if (!delta) return;
  e.preventDefault();
  auto = false;
  to = clamp(to + (delta / 100) * width);
}
function onLeave() {
  if (reduce || auto || dragging) return;
  clearTimeout(resumeTimer);
  resumeTimer = setTimeout(function () { auto = true; clock = 0; }, 4000);
}

const ro = new ResizeObserver(measure);
ro.observe(track);
measure();
x = to = width * 0.57;
render();
el.addEventListener('pointerdown', onDown);
el.addEventListener('pointermove', onMove);
el.addEventListener('pointerup', onUp);
el.addEventListener('pointercancel', onUp);
el.addEventListener('pointerleave', onLeave);
track.addEventListener('keydown', onKey);
raf = requestAnimationFrame(frame);

function dispose() {
  alive = false;
  cancelAnimationFrame(raf);
  clearTimeout(resumeTimer);
  ro.disconnect();
  el.removeEventListener('pointerdown', onDown);
  el.removeEventListener('pointermove', onMove);
  el.removeEventListener('pointerup', onUp);
  el.removeEventListener('pointercancel', onUp);
  el.removeEventListener('pointerleave', onLeave);
  track.removeEventListener('keydown', onKey);
}
return dispose;

