js:
const el = root.querySelector('.m-tilt-card-3d');
if (!el) return function () {};
const card = el.querySelector('.m-tilt-card-3d__card');
const content = el.querySelector('.m-tilt-card-3d__content');
const sheen = el.querySelector('.m-tilt-card-3d__sheen');
const reduce = window.matchMedia('(prefers-reduced-motion: reduce)').matches;

const MAX_Y = reduce ? 4 : 16, MAX_X = reduce ? 3 : 13;  // degrees
const K = 170, C = 20;                                   // spring(170, 20)
const rot = { x: 0, y: 0, vx: 0, vy: 0 };                // degrees
const lift = { x: 0, v: 0, to: 0 };                      // hover scale
const target = { x: 0, y: 0 };
let unit = 1, hovering = false, resumeAt = 0;
let raf = 0, last = 0, alive = true, seen = false, orphan = 0;

function measure() { unit = (el.clientHeight || 255) / 255; }
const ro = new ResizeObserver(measure);
ro.observe(el);
measure();

function onMove(e) {
  const r = el.getBoundingClientRect();
  const nx = Math.max(-1, Math.min(1, ((e.clientX - r.left) / r.width) * 2 - 1));
  const ny = Math.max(-1, Math.min(1, ((e.clientY - r.top) / r.height) * 2 - 1));
  hovering = true;
  lift.to = 1;
  target.y = nx * MAX_Y;   // cursor right: right edge tips away
  target.x = -ny * MAX_X;  // cursor low: bottom edge tips away
}
function onLeave() {
  hovering = false;
  lift.to = 0;
  target.x = target.y = 0;
  resumeAt = performance.now() + 1400;
}

function frame(now) {
  if (!alive) return;
  if (!root.isConnected && (seen || ++orphan > 180)) return dispose();
  seen = seen || root.isConnected;
  const dt = Math.min((now - last) / 1000, 0.032) || 0.016;
  last = now;

  if (!hovering && !reduce && now > resumeAt) {
    // Idle figure-8: the Y tilt runs at half the frequency of the X tilt.
    const t = now / 1000;
    target.y = Math.sin(t * 0.9) * 9;
    target.x = Math.sin(t * 1.8) * 5;
  }
  rot.vx += (-K * (rot.x - target.x) - C * rot.vx) * dt;
  rot.vy += (-K * (rot.y - target.y) - C * rot.vy) * dt;
  rot.x += rot.vx * dt;
  rot.y += rot.vy * dt;
  lift.v += (-K * (lift.x - lift.to) - C * lift.v) * dt;
  lift.x += lift.v * dt;

  const px = rot.y / 16, py = -rot.x / 13; // -1..1, where the light sits on the card
  card.style.transform = `rotateX(${rot.x.toFixed(3)}deg) rotateY(${rot.y.toFixed(3)}deg) scale(${(1 + 0.04 * lift.x).toFixed(4)})`;
  card.style.boxShadow = `${(-px * 16 * unit).toFixed(1)}px ${((14 - py * 12) * unit).toFixed(1)}px ${(32 * unit).toFixed(1)}px rgba(0, 0, 0, 0.55)`;
  sheen.style.transform = `translate3d(${(px * 30).toFixed(2)}%, ${(py * 24).toFixed(2)}%, 0)`;
  sheen.style.opacity = (0.5 + 0.4 * Math.min(1, Math.hypot(px, py))).toFixed(3);
  content.style.transform = `translate3d(${(-px * 3 * unit).toFixed(2)}px, ${(-py * 3 * unit).toFixed(2)}px, 0)`;
  raf = requestAnimationFrame(frame);
}

el.addEventListener('pointermove', onMove);
el.addEventListener('pointerleave', onLeave);
raf = requestAnimationFrame(frame);

function dispose() {
  alive = false;
  cancelAnimationFrame(raf);
  ro.disconnect();
  el.removeEventListener('pointermove', onMove);
  el.removeEventListener('pointerleave', onLeave);
}
return dispose;

