}

js:
const el = root.querySelector('.m-solar-eclipse-ring');
if (!el) return function () {};
const bloom = el.querySelector('.m-solar-eclipse-ring__bloom');
const light = el.querySelector('.m-solar-eclipse-ring__light');
const sphere = el.querySelector('.m-solar-eclipse-ring__sphere');
const rim = el.querySelector('.m-solar-eclipse-ring__rim');
const reduce = window.matchMedia('(prefers-reduced-motion: reduce)').matches;

// Gradient ids are document-global, so each mounted copy gets its own.
const uid = Math.random().toString(36).slice(2, 8);
const grads = el.querySelectorAll('radialGradient');
grads[0].id = 'm-solar-eclipse-ring-bloom-' + uid;
grads[1].id = 'm-solar-eclipse-ring-matte-' + uid;
bloom.setAttribute('fill', 'url(#' + grads[0].id + ')');
sphere.setAttribute('fill', 'url(#' + grads[1].id + ')');

const CX = 200, CY = 150, R = 62;
const PERIOD = 3.6;                    // seconds per orbit at rest
const RIM = 2 * Math.PI * 60.6;        // rim circumference
let angle = -0.7;                      // where the crescent sits, radians
let speed = 1, speedTo = 1;            // hover eases this toward 3.2
let raf = 0, last = 0, alive = true, seen = false, orphan = 0;

function render() {
  // The light disc slides out from behind the sphere by `d`; that offset is the crescent's thickness.
  const phase = 0.5 + 0.5 * Math.sin(angle * 2 + 1);
  const d = 1.3 + 4.2 * phase;
  const cos = Math.cos(angle), sin = Math.sin(angle), deg = (angle * 180) / Math.PI;
  light.setAttribute('cx', (CX + cos * d).toFixed(2));
  light.setAttribute('cy', (CY + sin * d).toFixed(2));
  // Bloom: a soft ellipse on the lit limb, wider when the crescent is thick.
  bloom.setAttribute('cx', (CX + cos * R).toFixed(2));
  bloom.setAttribute('cy', (CY + sin * R).toFixed(2));
  bloom.setAttribute('rx', (16 + 26 * phase).toFixed(2));
  bloom.setAttribute('transform', `rotate(${deg.toFixed(2)} ${(CX + cos * R).toFixed(2)} ${(CY + sin * R).toFixed(2)})`);
  bloom.style.opacity = (0.3 + 0.7 * phase).toFixed(3);
  // The matte sphere keeps its lit side facing the crescent.
  sphere.setAttribute('transform', `rotate(${deg.toFixed(2)} ${CX} ${CY})`);
  // Rim highlight: a short arc inside the limb that lengthens as the crescent thins.
  const arc = RIM * (0.34 - 0.2 * phase);
  rim.setAttribute('stroke-dasharray', `${arc.toFixed(2)} ${(RIM - arc).toFixed(2)}`);
  rim.setAttribute('transform', `rotate(${(deg - (arc / RIM) * 180).toFixed(2)} ${CX} ${CY})`);
  rim.style.strokeOpacity = (0.42 - 0.3 * phase).toFixed(3);
}

function frame(now) {
  if (!alive) return;
  if (!root.isConnected && (seen || ++orphan > 180)) return dispose();
  seen = seen || root.isConnected;
  const dt = Math.min((now - last) / 1000, 0.032) || 0.016;
  last = now;
  speed += (speedTo - speed) * (1 - Math.exp(-dt * 5));
  angle = (angle + (speed * dt * Math.PI * 2) / PERIOD) % (Math.PI * 2);
  render();
  raf = requestAnimationFrame(frame);
}

function onEnter() { speedTo = 3.2; }
function onLeave() { speedTo = 1; }

render();
el.addEventListener('pointerenter', onEnter);
el.addEventListener('pointerleave', onLeave);
if (!reduce) raf = requestAnimationFrame(frame);

function dispose() {
  alive = false;
  cancelAnimationFrame(raf);
  el.removeEventListener('pointerenter', onEnter);
  el.removeEventListener('pointerleave', onLeave);
}
return dispose;

