const el = root.querySelector('.m-infinity-path-loop');
if (!el) return function () {};
const run = el.querySelector('.m-infinity-path-loop__run');
const halo = el.querySelector('.m-infinity-path-loop__halo');
const reduce = window.matchMedia('(prefers-reduced-motion: reduce)').matches;

const total = run.getTotalLength();   // the path starts and ends at the crossover
const LAP = reduce ? 9.6 : 2.4;       // seconds per lap at rest
const LONG = 0.24, SHORT = 0.1;       // capsule length as a fraction of the path: on a lobe, at the crossover
let pos = total * 0.25;               // capsule centre, in path units
let boost = 0;                        // extra speed after a click, decays to zero
let raf = 0, last = 0, alive = true, seen = false, orphan = 0;

function render() {
  // 1 at the crossover (pos = 0 or total / 2), falling to 0 along the lobes.
  const half = total / 2;
  const off = Math.min(pos % half, half - (pos % half));
  const pinch = reduce ? 0 : Math.exp(-Math.pow(off / (total * 0.075), 2));
  const dash = total * (LONG - (LONG - SHORT) * pinch);
  const array = `${dash.toFixed(2)} ${(total - dash).toFixed(2)}`;
  const offset = (-(pos - dash / 2)).toFixed(2);
  run.setAttribute('stroke-dasharray', array);
  run.setAttribute('stroke-dashoffset', offset);
  halo.setAttribute('stroke-dasharray', array);
  halo.setAttribute('stroke-dashoffset', offset);
  run.setAttribute('stroke-width', (13 + 2.2 * Math.min(1, boost / 2.6)).toFixed(2));
  halo.style.strokeOpacity = (0.09 + 0.1 * Math.min(1, boost / 2.6)).toFixed(3);
  return pinch;
}

function frame(now) {
  if (!alive) return;
  if (!root.isConnected && (seen || ++orphan > 180)) return dispose();
  seen = seen || root.isConnected;
  const dt = Math.min((now - last) / 1000, 0.032) || 0.016;
  last = now;
  const pinch = render();
  boost *= Math.exp(-dt * 2.2);
  // The capsule whips through the crossover a little faster than it rounds the lobes.
  pos = (pos + (total / LAP) * (1 + 0.3 * pinch + boost) * dt) % total;
  raf = requestAnimationFrame(frame);
}

function onClick() { boost = reduce ? 0 : 2.6; }

render();
el.addEventListener('click', onClick);
raf = requestAnimationFrame(frame);

function dispose() {
  alive = false;
  cancelAnimationFrame(raf);
  el.removeEventListener('click', onClick);
}
return dispose;

