js:
const el = root.querySelector('.m-align-switch');
if (!el) return function () {};
const seg = el.querySelector('.m-align-switch__seg');
const pill = el.querySelector('.m-align-switch__pill');
const opts = Array.prototype.slice.call(el.querySelectorAll('.m-align-switch__opt'));
const text = el.querySelector('.m-align-switch__text');
const bars = Array.prototype.slice.call(text.children);
const reduce = window.matchMedia('(prefers-reduced-motion: reduce)').matches;

// Bar widths per alignment, as a fraction of the text block.
const WIDTHS = [[1, 0.66, 0.84], [0.72, 1, 0.5], [0.86, 0.58, 1]];
const timers = new Set();
let index = 0, optWidth = 46, blockWidth = 148;
let auto = !reduce, autoTimer = 0, resumeTimer = 0;
let raf = 0, last = 0, alive = true, running = false, seen = false, orphan = 0;

function spring(k, c, x) { return { x: x, v: 0, to: x, k: k, c: c }; }
const slide = spring(320, 26, 0);                                        // pill x, in segment widths
const lines = bars.map(function (bar, i) {
  return { align: spring(240, 22, 0), width: spring(240, 22, WIDTHS[0][i]) };
});
const all = [slide].concat(lines.map(function (l) { return l.align; }), lines.map(function (l) { return l.width; }));

function later(fn, ms) {
  const id = setTimeout(function () { timers.delete(id); fn(); }, ms);
  timers.add(id);
}

function measure() {
  optWidth = opts[0].offsetWidth || 46;
  blockWidth = text.clientWidth || 148;
  render();
}

function render() {
  const stretch = Math.min(0.28, Math.abs(slide.v) * 0.045);
  pill.style.transform = `translate3d(${(slide.x * optWidth).toFixed(2)}px, 0, 0) scaleX(${(1 + stretch).toFixed(4)})`;
  lines.forEach(function (line, i) {
    const w = Math.max(0.05, line.width.x) * blockWidth;
    bars[i].style.width = w.toFixed(2) + 'px';
    bars[i].style.transform = `translate3d(${(line.align.x * (blockWidth - w)).toFixed(2)}px, 0, 0)`;
  });
}

function frame(now) {
  if (!alive) return;
  if (!root.isConnected && (seen || ++orphan > 180)) return dispose();
  seen = seen || root.isConnected;
  const dt = Math.min((now - last) / 1000, 0.032) || 0.016;
  last = now;
  let moving = false;
  all.forEach(function (s) {
    if (reduce) { s.x = s.to; s.v = 0; return; }
    s.v += (-s.k * (s.x - s.to) - s.c * s.v) * dt;
    s.x += s.v * dt;
    if (Math.abs(s.v) > 0.002 || Math.abs(s.x - s.to) > 0.0005) moving = true;
  });
  render();
  // Sleep once everything has settled; select() wakes the loop again.
  if (moving) raf = requestAnimationFrame(frame); else running = false;
}
function wake() {
  if (running || !alive) return;
  running = true;
  last = performance.now();
  raf = requestAnimationFrame(frame);
}

function select(next) {
  index = next;
  opts.forEach(function (opt, i) {
    opt.classList.toggle('is-on', i === index);
    opt.setAttribute('aria-selected', String(i === index));
    opt.tabIndex = i === index ? 0 : -1;
  });
  slide.to = index;
  // Each bar starts 45ms after the one above it.
  lines.forEach(function (line, i) {
    later(function () {
      line.align.to = index / 2;
      line.width.to = WIDTHS[index][i];
      wake();
    }, reduce ? 0 : i * 45);
  });
  wake();
}

function demo() {
  clearTimeout(autoTimer);
  autoTimer = setTimeout(function () {
    if (!auto || !root.isConnected) return;
    select((index + 1) % 3);
    demo();
  }, 1500);
}
function stopDemo() {
  auto = false;
  clearTimeout(autoTimer);
  clearTimeout(resumeTimer);
}
function onClick(e) {
  const opt = e.target.closest('.m-align-switch__opt');
  if (!opt) return;
  stopDemo();
  select(opts.indexOf(opt));
}
function onKey(e) {
  const delta = e.key === 'ArrowRight' ? 1 : e.key === 'ArrowLeft' ? -1 : 0;
  if (!delta) return;
  e.preventDefault();
  stopDemo();
  select((index + delta + 3) % 3);
  opts[index].focus();
}
function onLeave() {
  if (reduce || auto) return;
  clearTimeout(resumeTimer);
  resumeTimer = setTimeout(function () { auto = true; demo(); }, 4000);
}

const ro = new ResizeObserver(measure);
ro.observe(el);
measure();
select(0);
seg.addEventListener('click', onClick);
seg.addEventListener('keydown', onKey);
el.addEventListener('pointerleave', onLeave);
if (auto) demo();

function dispose() {
  alive = false;
  cancelAnimationFrame(raf);
  clearTimeout(autoTimer);
  clearTimeout(resumeTimer);
  timers.forEach(clearTimeout);
  timers.clear();
  ro.disconnect();
  seg.removeEventListener('click', onClick);
  seg.removeEventListener('keydown', onKey);
  el.removeEventListener('pointerleave', onLeave);
}
return dispose;

