js:
const el = root.querySelector('.m-sonner-toast-stack');
if (!el) return function () {};
const list = el.querySelector('.m-sonner-toast-stack__list');
const pushBtn = el.querySelector('.m-sonner-toast-stack__push');
const reduce = window.matchMedia('(prefers-reduced-motion: reduce)').matches;

const K = 260, C = 24;        // spring(260, 24)
const VISIBLE = 3;
const COPY = [
  ['Event created', 'Monday at 9:00 AM'],
  ['Changes saved', 'All edits are synced'],
  ['Invite sent', 'To the design team'],
  ['Link copied', 'Ready to paste'],
  ['Export ready', 'report.pdf, 2.4 MB']
];
let toasts = [];              // newest first
let made = 0, unit = 1, height = 43;
let hover = false, demoOpen = false;
let auto = !reduce, autoTimer = 0, resumeTimer = 0;
let raf = 0, last = 0, alive = true, running = false, seen = false, orphan = 0;

function measure() {
  unit = (el.clientHeight || 255) / 255;
  height = 0.17 * (el.clientHeight || 255);
  layout();
}

function make(y, o) {
  const copy = COPY[made++ % COPY.length];
  const node = document.createElement('li');
  node.className = 'm-sonner-toast-stack__toast';
  node.innerHTML =
    '<span class="m-sonner-toast-stack__icon"><svg viewBox="0 0 16 16" aria-hidden="true"><path d="M3.5 8.4l3 3 6-6.6"/></svg></span>' +
    '<span class="m-sonner-toast-stack__body"><b></b><small></small></span>';
  node.querySelector('b').textContent = copy[0];
  node.querySelector('small').textContent = copy[1];
  list.appendChild(node);
  return { node: node, y: y, s: 1, o: o, vy: 0, vs: 0, vo: 0, ty: 0, ts: 1, to: 1 };
}

// Collapsed: each older toast peeks 10px higher and 6% smaller. Expanded: a full column.
function layout() {
  const open = hover || demoOpen;
  toasts.forEach(function (t, i) {
    t.ty = open ? -(height + 8 * unit) * i : -10 * unit * i;
    t.ts = open ? 1 : 1 - 0.06 * i;
    t.to = i < VISIBLE ? 1 : 0;
    t.node.style.zIndex = String(100 - i);
  });
  wake();
}

function push() {
  toasts.unshift(make(height + 12 * unit, 0)); // enters from below the stack
  layout();
}

function render(t) {
  t.node.style.transform = `translate3d(0, ${t.y.toFixed(2)}px, 0) scale(${t.s.toFixed(4)})`;
  t.node.style.opacity = Math.max(0, Math.min(1, t.o)).toFixed(3);
}

function frame(now) {
  if (!alive) return;
  if (!root.isConnected && (seen || ++orphan > 180)) return dispose();
  seen = seen || root.isConnected;
  const dt = Math.min((now - last) / 1000, 0.032) || 0.016;
  last = now;
  let moving = false;
  toasts.forEach(function (t) {
    if (reduce) {
      t.y = t.ty; t.s = t.ts; t.o = t.to;
    } else {
      t.vy += (-K * (t.y - t.ty) - C * t.vy) * dt;  t.y += t.vy * dt;
      t.vs += (-K * (t.s - t.ts) - C * t.vs) * dt;  t.s += t.vs * dt;
      t.vo += (-K * (t.o - t.to) - C * t.vo) * dt;  t.o += t.vo * dt;
      if (Math.abs(t.vy) > 0.5 || Math.abs(t.y - t.ty) > 0.05 || Math.abs(t.o - t.to) > 0.004 || Math.abs(t.s - t.ts) > 0.0005) moving = true;
    }
    render(t);
  });
  // Drop toasts that have faded out behind the stack.
  toasts = toasts.filter(function (t, i) {
    if (i < VISIBLE || t.o > 0.02) return true;
    t.node.remove();
    return false;
  });
  if (moving) raf = requestAnimationFrame(frame); else running = false;
}
function wake() {
  if (running || !alive) return;
  running = true;
  last = performance.now();
  raf = requestAnimationFrame(frame);
}

// Auto-demo: fan out, fold back, push one, repeat.
function demo(stage) {
  clearTimeout(autoTimer);
  autoTimer = setTimeout(function () {
    if (!auto || !root.isConnected) return;
    if (stage === 0) { demoOpen = true; layout(); }
    if (stage === 1) { demoOpen = false; layout(); }
    if (stage === 2) push();
    demo((stage + 1) % 3);
  }, stage === 0 ? 1100 : stage === 1 ? 1700 : 1000);
}
function stopDemo() {
  auto = false;
  demoOpen = false;
  clearTimeout(autoTimer);
  clearTimeout(resumeTimer);
}
function onEnter() { stopDemo(); hover = true; layout(); }
function onExit() { hover = false; layout(); }
function onPush() { stopDemo(); push(); }
function onLeave() {
  if (reduce) return;
  clearTimeout(resumeTimer);
  resumeTimer = setTimeout(function () { auto = true; demo(0); }, 4000);
}

const ro = new ResizeObserver(measure);
ro.observe(el);
unit = (el.clientHeight || 255) / 255;
height = 0.17 * (el.clientHeight || 255);
for (let i = 0; i < VISIBLE; i++) toasts.unshift(make(0, 1));
layout();
toasts.forEach(function (t) { t.y = t.ty; t.s = t.ts; t.o = t.to; render(t); });
list.addEventListener('pointerenter', onEnter);
list.addEventListener('pointerleave', onExit);
pushBtn.addEventListener('click', onPush);
el.addEventListener('pointerleave', onLeave);
if (auto) demo(0);

function dispose() {
  alive = false;
  cancelAnimationFrame(raf);
  clearTimeout(autoTimer);
  clearTimeout(resumeTimer);
  ro.disconnect();
  list.removeEventListener('pointerenter', onEnter);
  list.removeEventListener('pointerleave', onExit);
  pushBtn.removeEventListener('click', onPush);
  el.removeEventListener('pointerleave', onLeave);
}
return dispose;

