const el = root.querySelector('.m-vaul-spring-drawer');
if (!el) return function () {};
const phone = el.querySelector('.m-vaul-spring-drawer__phone');
const app = el.querySelector('.m-vaul-spring-drawer__app');
const scrim = el.querySelector('.m-vaul-spring-drawer__scrim');
const sheet = el.querySelector('.m-vaul-spring-drawer__sheet');
const reduce = window.matchMedia('(prefers-reduced-motion: reduce)').matches;

const K = 300, C = 28;        // spring(300, 28)
let unit = 1;                 // px per design px (design stage is 255px tall)
let phoneH = 224;
let travel = 130;             // distance from open (0) to closed, px
let y = 130, v = 0, to = 130; // sheet offset spring
let open = false;
let dragging = false, moved = false, startY = 0, startOffset = 0, lastY = 0, lastT = 0, dragV = 0;
let auto = !reduce, autoTimer = 0, resumeTimer = 0;
let raf = 0, last = 0, alive = true, running = false, seen = false, orphan = 0;

function measure() {
  unit = (el.clientHeight || 255) / 255;
  phoneH = phone.clientHeight || 224;
  travel = phoneH * 0.6;
  if (!dragging) { to = open ? 0 : travel; y = to; v = 0; }
  render();
}

function render() {
  const p = Math.max(0, Math.min(1, 1 - y / travel)); // 0 closed, 1 open
  const radius = (12 * unit * p).toFixed(2);
  sheet.style.transform = `translate3d(0, ${y.toFixed(2)}px, 0)`;
  app.style.transform = `translate3d(0, ${(p * 0.035 * phoneH).toFixed(2)}px, 0) scale(${(1 - 0.06 * p).toFixed(4)})`;
  app.style.borderRadius = `${radius}px ${radius}px 0 0`;
  scrim.style.opacity = (0.42 * p).toFixed(3);
}

function frame(now) {
  if (!alive) return;
  if (!root.isConnected && (seen || ++orphan > 180)) return dispose();
  seen = seen || root.isConnected;
  const dt = Math.min((now - last) / 1000, 0.032) || 0.016;
  last = now;
  if (!dragging) {
    if (reduce) { y = to; v = 0; }
    else {
      v += (-K * (y - to) - C * v) * dt;
      y += v * dt;
    }
  }
  render();
  const moving = dragging || Math.abs(v) > 0.5 || Math.abs(y - to) > 0.05;
  if (moving) raf = requestAnimationFrame(frame); else running = false;
}
function wake() {
  if (running || !alive) return;
  running = true;
  last = performance.now();
  raf = requestAnimationFrame(frame);
}

function setOpen(next, velocity) {
  open = next;
  to = open ? 0 : travel;
  v = velocity || 0;
  sheet.setAttribute('aria-hidden', String(!open));
  wake();
}

function onDown(e) {
  stopDemo();
  dragging = true;
  moved = false;
  startY = lastY = e.clientY;
  startOffset = y;
  lastT = performance.now();
  dragV = 0;
  sheet.classList.add('is-dragging');
  if (sheet.setPointerCapture) { try { sheet.setPointerCapture(e.pointerId); } catch (err) {} }
  wake();
}
function onMove(e) {
  if (!dragging) return;
  const raw = startOffset + (e.clientY - startY);
  if (Math.abs(e.clientY - startY) > 4 * unit) moved = true;
  // Down follows the finger 1:1. Up past the open position meets rubber-band resistance.
  const limit = phoneH * 0.1;
  y = raw < 0 ? -limit * (1 - Math.exp(raw / limit)) : Math.min(raw, travel);
  const now = performance.now();
  if (now > lastT) dragV = 0.6 * dragV + 0.4 * ((e.clientY - lastY) / (now - lastT)) * 1000;
  lastY = e.clientY;
  lastT = now;
}
function onUp() {
  if (!dragging) return;
  dragging = false;
  sheet.classList.remove('is-dragging');
  if (!moved) return setOpen(!open, 0);               // a tap toggles
  const close = y > travel * 0.35 || dragV > 600 * unit;
  setOpen(!close, y < 0 ? 0 : dragV);                 // keep the release velocity
}
function onPhoneClick(e) {
  if (sheet.contains(e.target)) return;
  stopDemo();
  setOpen(!open, 0);
}

function demo() {
  clearTimeout(autoTimer);
  autoTimer = setTimeout(function () {
    if (!auto || !root.isConnected) return;
    setOpen(!open, 0);
    demo();
  }, open ? 2100 : 1100);
}
function stopDemo() {
  auto = false;
  clearTimeout(autoTimer);
  clearTimeout(resumeTimer);
}
function onLeave() {
  if (reduce || auto || dragging) return;
  clearTimeout(resumeTimer);
  resumeTimer = setTimeout(function () { auto = true; demo(); }, 4000);
}

const ro = new ResizeObserver(measure);
ro.observe(el);
measure();
sheet.setAttribute('aria-hidden', 'true');
sheet.addEventListener('pointerdown', onDown);
sheet.addEventListener('pointermove', onMove);
sheet.addEventListener('pointerup', onUp);
sheet.addEventListener('pointercancel', onUp);
phone.addEventListener('click', onPhoneClick);
el.addEventListener('pointerleave', onLeave);
if (auto) demo();

function dispose() {
  alive = false;
  cancelAnimationFrame(raf);
  clearTimeout(autoTimer);
  clearTimeout(resumeTimer);
  ro.disconnect();
  sheet.removeEventListener('pointerdown', onDown);
  sheet.removeEventListener('pointermove', onMove);
  sheet.removeEventListener('pointerup', onUp);
  sheet.removeEventListener('pointercancel', onUp);
  phone.removeEventListener('click', onPhoneClick);
  el.removeEventListener('pointerleave', onLeave);
}
return dispose;
